; ============================================================================
;	cpu_test.asm
;	CPU test : runner (ASCII8K mega ROM, bank 0-1 at 4000h-7FFFh)
;
;	The test stream (bank 2 and later) is generated by make_tests.py.
;	Display: SCREEN 1, COLOR 15,4,7
;		row 0     : TOT / DONE / ERR (fixed)
;		row 1     : progress (CPU, test number, instruction, spinner)
;		row 2     : separator
;		row 3-23  : scrolling log
; ============================================================================

			include	"cpu_test_def.asm"

; BIOS
ENASLT			:= 0x0024
MSXVER			:= 0x002D
CHGMOD			:= 0x005F
CHGCLR			:= 0x0062
RSLREG			:= 0x0138
SNSMAT			:= 0x0141
CHGCPU			:= 0x0180
RG1SAV			:= 0xF3E0
FORCLR			:= 0xF3E9
BAKCLR			:= 0xF3EA
BDRCLR			:= 0xF3EB
EXPTBL			:= 0xFCC1

; I/O
VDP_DATA		:= 0x98
VDP_CTRL		:= 0x99
PPI_SLOT		:= 0xA8

; ASCII8K bank registers
BANK0			:= 0x6000
BANK1			:= 0x6800
BANK2			:= 0x7000
BANK3			:= 0x7800

NAME_TBL		:= 0x1800
SCROLL_TOP		:= 3
SCROLL_ROWS		:= 21
STACK_TOP		:= 0xF000
DATA_OFFSET		:= 0x4000
DETAIL_LINES	:= 4

; stub header
STUB_ENTRY		:= STUB_ADDR + 0
STUB_SAVE_N		:= STUB_ADDR + 4
STUB_SAVE_T		:= STUB_ADDR + 6
STUB_SAVE_RST	:= STUB_ADDR + 8
STUB_ALU_ROW	:= STUB_ADDR + 24
STUB_ALU_FA		:= STUB_ADDR + 26
STUB_ALU_SEL	:= STUB_ADDR + 28
STUB_ALU_OP		:= STUB_ADDR + 30
STUB_ALU_MASK	:= STUB_ADDR + 32

; work area
WORK			:= 0xE100
rnd_state		:= WORK + 0x00		; 2
strm_ptr		:= WORK + 0x02		; 2
strm_bank		:= WORK + 0x04		; 1
cpu_mode		:= WORK + 0x05		; 0: Z80, 1: R800
is_turbor		:= WORK + 0x06
my_slot			:= WORK + 0x07
orig_a8			:= WORK + 0x08
test_a8			:= WORK + 0x09
ram_exp			:= WORK + 0x0A
orig_ssl		:= WORK + 0x0B
test_ssl		:= WORK + 0x0C
spin			:= WORK + 0x0D
total			:= WORK + 0x0E		; 2
done_cnt		:= WORK + 0x10		; 2
err_cnt			:= WORK + 0x12		; 2
r800_count		:= WORK + 0x14		; 2
r800_off		:= WORK + 0x16		; 3
t_len			:= WORK + 0x19
t_fmask			:= WORK + 0x1A
t_flags			:= WORK + 0x1B
t_nstat			:= WORK + 0x1C
t_nvec			:= WORK + 0x1D		; 2
vec_no			:= WORK + 0x1F		; 2
vec_err			:= WORK + 0x21		; 2
mism			:= WORK + 0x23
detail			:= WORK + 0x24
rel_addr		:= WORK + 0x25		; 2
lb_ptr			:= WORK + 0x27		; 2
t_nf			:= WORK + 0x29
t_na			:= WORK + 0x2A
t_frow			:= WORK + 0x2B
t_arow			:= WORK + 0x2C
z80_count		:= WORK + 0x2D		; 2
zt_got			:= WORK + 0x2F		; 4 ( z80test CRC, MSB first )
zt_ncrc			:= WORK + 0x33
skip_z80		:= WORK + 0x34		; 1: skip the Z80 suite ( [R] key at boot, turbo R only )
name_buf		:= WORK + 0x40		; 32
stat_buf		:= WORK + 0x60		; 96 (32 entries)
flist_buf		:= WORK + 0xC0		; 16
line_buf		:= WORK + 0xD0		; 32
LINE_END		:= WORK + 0xF0
SHADOW			:= 0xE200			; SCROLL_ROWS * 32

; ----------------------------------------------------------------------------
;	ROM header
; ----------------------------------------------------------------------------
			org		0x4000
rom_header:
			defb	0x41, 0x42
			defw	rom_init
			defw	0, 0, 0
			space	6, 0

rom_init:
			di
			ld		sp, STACK_TOP
			xor		a, a
			ld		[BANK0], a
			inc		a
			ld		[BANK1], a
			jp		main

; ----------------------------------------------------------------------------
;	main
; ----------------------------------------------------------------------------
main:
			call	get_my_slot
			ld		a, [my_slot]
			ld		h, 0x80
			call	ENASLT
			di
			ld		a, 4
			call	SNSMAT
			di
			cpl
			rlca
			and		a, 1
			ld		[skip_z80], a
			ld		a, [MSXVER]
			cp		a, 3
			ld		a, 0
			jr		c, main_not_turbor
			inc		a
main_not_turbor:
			ld		[is_turbor], a
			xor		a, a
			ld		[cpu_mode], a
			ld		[spin], a
			ld		hl, 0
			ld		[done_cnt], hl
			ld		[err_cnt], hl
			ld		[total], hl

			ld		hl, stub_image
			ld		de, STUB_ADDR
			ld		bc, stub_image_end - stub_image
			ldir

			call	init_screen
			call	setup_ram_slot

			xor		a, a
			ld		hl, DATA_OFFSET
			call	stream_open
			ld		de, magic
			ld		b, 4
main_magic:
			call	rd_byte
			ex		de, hl
			cp		a, [hl]
			ex		de, hl
			jp		nz, bad_stream
			inc		de
			djnz	main_magic
			call	rd_word
			ld		[z80_count], hl
			call	rd_word
			ld		[r800_count], hl
			call	rd_word
			ld		[r800_off], hl
			call	rd_byte
			ld		[r800_off + 2], a
			ld		hl, [z80_count]
			ld		a, [is_turbor]
			or		a, a
			jr		z, main_total
			ld		de, [r800_count]
			add		hl, de
main_total:
			ld		[total], hl
			call	draw_status

			call	enter_test_map
			xor		a, a
			ld		[cpu_mode], a
			ld		a, [is_turbor]
			ld		b, a
			ld		a, [skip_z80]
			and		a, b
			jr		z, main_z80
			ld		hl, [z80_count]
			ld		[done_cnt], hl
			call	draw_status
			jr		main_z80_done
main_z80:
			call	run_suite
main_z80_done:

			ld		a, [is_turbor]
			or		a, a
			jr		nz, main_r800
			call	lb_clear
			ld		de, msg_no_r800
			call	lb_str
			call	emit_line
			jr		main_finish
main_r800:
			call	leave_test_map
			ld		a, 0x81
			call	CHGCPU
			di
			call	enter_test_map
			ld		a, 1
			ld		[cpu_mode], a
			ld		hl, [r800_off]
			ld		a, [r800_off + 2]
			call	stream_open
			call	run_suite

main_finish:
			call	lb_clear
			ld		de, msg_finish
			call	lb_str
			ld		hl, [err_cnt]
			ld		a, h
			or		a, l
			ld		de, msg_all_ok
			jr		z, main_finish_msg
			ld		de, msg_some_ng
main_finish_msg:
			call	lb_str
			ld		a, 1
			call	write_row
main_halt:
			jr		main_halt

bad_stream:
			call	lb_clear
			ld		de, msg_bad_stream
			call	lb_str
			call	emit_line
bad_stream_halt:
			jr		bad_stream_halt

; ----------------------------------------------------------------------------
;	slot handling
; ----------------------------------------------------------------------------
get_my_slot:
			call	RSLREG
			rrca
			rrca
			and		a, 3
			ld		c, a
			ld		b, 0
			ld		hl, EXPTBL
			add		hl, bc
			ld		a, [hl]
			and		a, 0x80
			or		a, c
			ld		c, a
			jp		p, get_my_slot_done
			inc		hl
			inc		hl
			inc		hl
			inc		hl
			ld		a, [hl]
			and		a, 0x0C
			or		a, c
			ld		c, a
get_my_slot_done:
			ld		a, c
			ld		[my_slot], a
			ret

setup_ram_slot:
			in		a, [PPI_SLOT]
			ld		[orig_a8], a
			ld		b, a
			rlca
			rlca
			and		a, 3
			ld		c, a
			ld		a, b
			and		a, 0xFC
			or		a, c
			ld		[test_a8], a
			ld		b, 0
			ld		hl, EXPTBL
			add		hl, bc
			ld		a, [hl]
			and		a, 0x80
			ld		[ram_exp], a
			ret		z
			ld		a, [0xFFFF]
			cpl
			ld		[orig_ssl], a
			ld		b, a
			rlca
			rlca
			and		a, 3
			ld		c, a
			ld		a, b
			and		a, 0xFC
			or		a, c
			ld		[test_ssl], a
			ret

; page0 <- RAM (same slot as page3), and write the RST vectors
enter_test_map:
			ld		a, [test_a8]
			out		[PPI_SLOT], a
			ld		a, [ram_exp]
			or		a, a
			jr		z, enter_test_map_vec
			ld		a, [test_ssl]
			ld		[0xFFFF], a
enter_test_map_vec:
			ld		hl, STUB_SAVE_RST
			ld		de, 0x0000
			ld		b, 8
enter_test_map_loop:
			ld		a, 0xC3
			ld		[de], a
			inc		de
			ld		a, [hl]
			ld		[de], a
			inc		hl
			inc		de
			ld		a, [hl]
			ld		[de], a
			inc		hl
			ld		a, e
			add		a, 6
			ld		e, a
			djnz	enter_test_map_loop
			ret

; page0 <- BIOS
leave_test_map:
			ld		a, [ram_exp]
			or		a, a
			jr		z, leave_test_map_a8
			ld		a, [orig_ssl]
			ld		[0xFFFF], a
leave_test_map_a8:
			ld		a, [orig_a8]
			out		[PPI_SLOT], a
			ret

; ----------------------------------------------------------------------------
;	stream reader
; ----------------------------------------------------------------------------
;	input: a:hl = ROM file offset
stream_open:
			ld		c, a
			ld		a, h
			and		a, 0x1F
			or		a, 0x80
			ld		b, a
			ld		a, h
			rlca
			rlca
			rlca
			and		a, 7
			ld		d, a
			ld		a, c
			add		a, a
			add		a, a
			add		a, a
			or		a, d
			ld		[strm_bank], a
			ld		[BANK2], a
			inc		a
			ld		[BANK3], a
			ld		h, b
			ld		[strm_ptr], hl
			ret

;	output: a = next byte (bc, de, hl are preserved)
rd_byte:
			push	hl
			ld		hl, [strm_ptr]
			ld		a, [hl]
			inc		hl
			bit		5, h
			jr		nz, rd_byte_next_bank
			ld		[strm_ptr], hl
			pop		hl
			ret
rd_byte_next_bank:
			ld		h, 0x80
			ld		[strm_ptr], hl
			push	af
			ld		a, [strm_bank]
			inc		a
			ld		[strm_bank], a
			ld		[BANK2], a
			inc		a
			ld		[BANK3], a
			pop		af
			pop		hl
			ret

;	output: hl = next word
rd_word:
			call	rd_byte
			ld		l, a
			call	rd_byte
			ld		h, a
			ret

;	input: hl = base address ( pairs of offset, value )
rd_pairs:
			call	rd_byte
			or		a, a
			ret		z
			ld		b, a
rd_pairs_loop:
			call	rd_byte
			ld		e, a
			ld		d, 0
			push	hl
			add		hl, de
			call	rd_byte
			ld		[hl], a
			pop		hl
			djnz	rd_pairs_loop
			ret

read_name:
			ld		de, name_buf
read_name_loop:
			call	rd_byte
			ld		[de], a
			inc		de
			or		a, a
			jr		nz, read_name_loop
			ret

; ----------------------------------------------------------------------------
;	suite
; ----------------------------------------------------------------------------
run_suite:
			call	rd_byte
			cp		a, 0xFF
			ret		z
			or		a, a
			jr		z, run_suite_vector
			cp		a, 1
			jr		z, run_suite_alu
			cp		a, 2
			jr		z, run_suite_zt
			cp		a, 4
			jr		z, run_suite_special
			cp		a, 3
			jp		nz, bad_stream
			call	zt_load
			jr		run_suite
run_suite_special:
			call	special_test
			jr		run_suite
run_suite_zt:
			call	zt_run
			jr		run_suite
run_suite_alu:
			call	alu_test
			jr		run_suite
run_suite_vector:
			call	vector_test
			jr		run_suite

test_begin:
			ld		hl, 0
			ld		[vec_no], hl
			ld		[vec_err], hl
			ret

test_end:
			ld		hl, [vec_err]
			ld		a, h
			or		a, l
			jr		z, test_end_ok
			call	lb_clear
			ld		de, msg_summary
			call	lb_str
			ld		hl, [vec_err]
			call	lb_dec5
			ld		a, 0x2F
			call	lb_chr
			ld		hl, [vec_no]
			call	lb_dec5
			call	emit_line
			ld		hl, [err_cnt]
			inc		hl
			ld		[err_cnt], hl
test_end_ok:
			ld		hl, [done_cnt]
			inc		hl
			ld		[done_cnt], hl
			jp		draw_status

vec_next:
			ld		hl, [vec_no]
			inc		hl
			ld		[vec_no], hl
			ld		a, l
			and		a, 0x0F
			ret		nz
			jp		spin_step

; ----------------------------------------------------------------------------
;	vector test
; ----------------------------------------------------------------------------
vector_test:
			call	read_name
			call	show_progress
			call	rd_byte
			ld		[t_len], a
			call	rd_byte
			ld		[t_fmask], a
			call	rd_byte
			ld		[t_flags], a
			call	rd_byte
			ld		[t_nstat], a
			or		a, a
			jr		z, vector_test_seed
			ld		b, a
			ld		de, stat_buf
vector_test_stat:
			call	rd_byte
			ld		[de], a
			inc		de
			call	rd_byte
			ld		[de], a
			inc		de
			call	rd_byte
			ld		[de], a
			inc		de
			djnz	vector_test_stat
vector_test_seed:
			call	rd_word
			ld		[rnd_state], hl
			call	rd_word
			ld		[t_nvec], hl

			ld		hl, THREAD_ADDR
			ld		de, THREAD_ADDR + 1
			ld		bc, THREAD_SIZE - 1
			ld		[hl], 0xFF
			ldir
			ld		hl, TGT_ADDR
			ld		de, [STUB_SAVE_T]
			call	put_jp
			call	test_begin

vector_test_loop:
			ld		hl, [vec_no]
			ld		de, [t_nvec]
			or		a, a
			sbc		hl, de
			jp		nc, test_end

			call	fill_isb
			call	apply_stat
			ld		hl, ISB
			call	rd_pairs
			ld		hl, ISB
			ld		de, EXPB
			ld		bc, STATE_SIZE
			ldir
			xor		a, a
			ld		[EXPB + O_PATH], a
			ld		hl, EXPB
			call	rd_pairs

			ld		hl, ISB + O_INS
			ld		de, INS_ADDR
			ld		bc, 4
			ldir
			ld		a, [t_len]
			ld		l, a
			ld		h, 0
			ld		de, INS_ADDR
			add		hl, de
			ld		de, [STUB_SAVE_N]
			call	put_jp
			ld		a, [t_flags]
			and		a, 1
			jr		z, vector_test_win
			ld		a, [t_len]
			ld		c, a
			ld		b, 0
			ld		hl, ISB + O_INS - 1
			add		hl, bc
			ld		l, [hl]
			ld		h, 0
			bit		7, l
			jr		z, vector_test_rel_pos
			dec		h
vector_test_rel_pos:
			add		hl, bc
			ld		de, INS_ADDR
			add		hl, de
			ld		[rel_addr], hl
			ld		de, [STUB_SAVE_T]
			call	put_jp
vector_test_win:
			ld		hl, ISB + O_WIN
			ld		de, WIN_ADDR
			ld		bc, WIN_SIZE
			ldir

			call	call_stub

			ld		hl, WIN_ADDR
			ld		de, OUTB + O_WIN
			ld		bc, WIN_SIZE
			ldir
			ld		a, [t_flags]
			and		a, 1
			jr		z, vector_test_cmp
			ld		hl, [rel_addr]
			ld		[hl], 0xFF
			inc		hl
			ld		[hl], 0xFF
			inc		hl
			ld		[hl], 0xFF
vector_test_cmp:
			call	compare_vec
			call	vec_next
			jp		vector_test_loop

call_stub:
			ld		hl, [STUB_ENTRY]
			jp		hl

;	input: hl = address, de = destination
put_jp:
			ld		[hl], 0xC3
			inc		hl
			ld		[hl], e
			inc		hl
			ld		[hl], d
			ret

; xorshift16 (7,9,8)
xrnd:
			ld		hl, [rnd_state]
			ld		a, h
			rra
			ld		a, l
			rra
			xor		a, h
			ld		h, a
			ld		a, l
			rra
			ld		a, h
			rra
			xor		a, l
			ld		l, a
			xor		a, h
			ld		h, a
			ld		[rnd_state], hl
			ret

fill_isb:
			ld		de, ISB
			ld		b, STATE_SIZE / 2
fill_isb_loop:
			call	xrnd
			ld		a, l
			ld		[de], a
			inc		de
			ld		a, h
			ld		[de], a
			inc		de
			djnz	fill_isb_loop
			ret

apply_stat:
			ld		a, [t_nstat]
			or		a, a
			ret		z
			ld		b, a
			ld		de, stat_buf
			ld		h, ISB >> 8
apply_stat_loop:
			ld		a, [de]
			inc		de
			ld		l, a
			ld		a, [de]
			inc		de
			and		a, [hl]
			ld		c, a
			ld		a, [de]
			inc		de
			or		a, c
			ld		[hl], a
			djnz	apply_stat_loop
			ret

compare_vec:
			xor		a, a
			ld		[mism], a
			ld		c, 0
compare_vec_loop:
			ld		a, c
			cp		a, O_INS
			jr		nz, compare_vec_get
			ld		c, O_WIN
compare_vec_get:
			ld		h, OUTB >> 8
			ld		a, c
			add		a, OUTB & 0xFF
			ld		l, a
			ld		b, [hl]
			ld		h, EXPB >> 8
			ld		a, c
			add		a, EXPB & 0xFF
			ld		l, a
			ld		a, [hl]
			xor		a, b
			ld		d, a
			ld		a, c
			or		a, a
			ld		a, d
			jr		nz, compare_vec_chk
			ld		a, [t_fmask]
			and		a, d
compare_vec_chk:
			or		a, a
			call	nz, report_field
			inc		c
			ld		a, c
			cp		a, STATE_SIZE
			jr		c, compare_vec_loop
			ret

;	input: c = offset, b = value got
report_field:
			push	bc
			ld		a, [mism]
			inc		a
			ld		[mism], a
			cp		a, 1
			jr		nz, report_field_detail
			ld		hl, [vec_err]
			inc		hl
			ld		[vec_err], hl
			dec		hl
			ld		a, h
			or		a, l
			ld		a, 0
			jr		nz, report_field_set
			call	print_ng_header
			ld		a, DETAIL_LINES
report_field_set:
			ld		[detail], a
report_field_detail:
			ld		a, [detail]
			or		a, a
			jr		z, report_field_end
			dec		a
			ld		[detail], a
			call	lb_clear
			ld		de, msg_indent
			call	lb_str
			pop		bc
			push	bc
			ld		a, c
			call	lb_field_name
			ld		de, msg_in
			call	lb_str
			pop		bc
			push	bc
			ld		l, c
			ld		h, ISB >> 8
			ld		a, [hl]
			call	lb_hex8
			ld		de, msg_exp
			call	lb_str
			pop		bc
			push	bc
			ld		a, c
			add		a, EXPB & 0xFF
			ld		l, a
			ld		h, EXPB >> 8
			ld		a, [hl]
			call	lb_hex8
			ld		de, msg_got
			call	lb_str
			pop		bc
			push	bc
			ld		a, b
			call	lb_hex8
			call	emit_line
report_field_end:
			pop		bc
			ret

print_ng_header:
			call	lb_clear
			ld		de, msg_ng
			call	lb_str
			call	lb_cpu
			ld		de, name_buf
			call	lb_str
			call	emit_line
			call	lb_clear
			ld		de, msg_vec
			call	lb_str
			ld		hl, [vec_no]
			call	lb_dec5
			ld		de, msg_ins
			call	lb_str
			ld		hl, ISB + O_INS
			ld		b, 4
print_ng_header_ins:
			ld		a, [hl]
			call	lb_hex8
			ld		a, 0x20
			call	lb_chr
			inc		hl
			djnz	print_ng_header_ins
			jp		emit_line

;	input: a = state block offset
lb_field_name:
			cp		a, O_WIN
			jr		nc, lb_field_name_win
			ld		l, a
			ld		h, 0
			ld		e, l
			ld		d, h
			add		hl, hl
			add		hl, de
			ld		de, field_names
			add		hl, de
			ld		b, 3
lb_field_name_loop:
			ld		a, [hl]
			call	lb_chr
			inc		hl
			djnz	lb_field_name_loop
			ret
lb_field_name_win:
			sub		a, O_WIN
			push	af
			ld		a, 0x4D
			call	lb_chr
			pop		af
			jp		lb_hex8

; ----------------------------------------------------------------------------
;	ALU exhaustive test
; ----------------------------------------------------------------------------
alu_test:
			call	read_name
			call	show_progress
			call	rd_byte
			ld		hl, [STUB_ALU_SEL]
			ld		[hl], a
			call	rd_byte
			ld		hl, [STUB_ALU_OP]
			ld		[hl], a
			call	rd_byte
			inc		hl
			ld		[hl], a
			call	rd_byte
			ld		hl, [STUB_ALU_MASK]
			ld		[hl], a
			call	rd_byte
			ld		[t_nf], a
			ld		b, a
			ld		de, flist_buf
alu_test_flist:
			call	rd_byte
			ld		[de], a
			inc		de
			djnz	alu_test_flist
			call	rd_byte
			ld		[t_na], a
			call	test_begin
			ld		de, flist_buf
			ld		a, [t_nf]
			ld		[t_frow], a
alu_test_f:
			ld		a, [de]
			push	de
			ld		hl, [STUB_ALU_FA]
			ld		[hl], a
			xor		a, a
			ld		[t_arow], a
alu_test_a:
			ld		a, [t_arow]
			ld		hl, [STUB_ALU_FA]
			inc		hl
			ld		[hl], a
			call	call_alu
			call	rd_byte
			ld		c, a
			call	rd_byte
			ld		b, a
			ld		a, c
			cp		a, e
			jr		nz, alu_test_bad
			ld		a, b
			cp		a, d
			jr		z, alu_test_ok
alu_test_bad:
			call	alu_report
alu_test_ok:
			call	vec_next
			ld		a, [t_arow]
			inc		a
			ld		[t_arow], a
			ld		hl, t_na
			cp		a, [hl]
			jr		nz, alu_test_a
			pop		de
			inc		de
			ld		a, [t_frow]
			dec		a
			ld		[t_frow], a
			jr		nz, alu_test_f
			jp		test_end

call_alu:
			ld		hl, [STUB_ALU_ROW]
			jp		hl

;	input: bc = expected, de = got
alu_report:
			push	bc
			push	de
			ld		hl, [vec_err]
			inc		hl
			ld		[vec_err], hl
			ld		a, h
			or		a, a
			jr		nz, alu_report_end
			ld		a, l
			cp		a, 1
			jr		nz, alu_report_row
			call	lb_clear
			ld		de, msg_ng
			call	lb_str
			call	lb_cpu
			ld		de, name_buf
			call	lb_str
			call	emit_line
alu_report_row:
			ld		a, [vec_err]
			cp		a, DETAIL_LINES + 1
			jr		nc, alu_report_end
			call	lb_clear
			ld		de, msg_alu_f
			call	lb_str
			ld		hl, [STUB_ALU_FA]
			ld		a, [hl]
			call	lb_hex8
			ld		de, msg_alu_a
			call	lb_str
			ld		a, [t_arow]
			call	lb_hex8
			ld		de, msg_exp
			call	lb_str
			pop		de
			pop		bc
			push	bc
			push	de
			ld		h, b
			ld		l, c
			call	lb_hex16
			ld		de, msg_got
			call	lb_str
			pop		de
			push	de
			ex		de, hl
			call	lb_hex16
			call	emit_line
alu_report_end:
			pop		de
			pop		bc
			ret

; ----------------------------------------------------------------------------
;	z80test port ( zt_engine.asm )
; ----------------------------------------------------------------------------
;	[03][length 16][engine image] : load the engine to ZT_ADDR and call zt_init
zt_load:
			call	rd_word
			ld		b, h
			ld		c, l
			ld		de, ZT_ADDR
zt_load_loop:
			call	rd_byte
			ld		[de], a
			inc		de
			dec		bc
			ld		a, b
			or		a, c
			jr		nz, zt_load_loop
			ld		hl, [ZT_ADDR + 0]
			jp		hl

;	[02][name 0][ncrc]{[crc 4 (MSB first)][label 0]}*ncrc[reclen][record]
zt_run:
			call	read_name
			call	show_progress
			call	rd_byte
			ld		[zt_ncrc], a
			ld		b, a
			ld		de, stat_buf
zt_run_crc:
			push	bc
			ld		b, 4
zt_run_crc_val:
			call	rd_byte
			ld		[de], a
			inc		de
			djnz	zt_run_crc_val
zt_run_crc_label:
			call	rd_byte
			ld		[de], a
			inc		de
			or		a, a
			jr		nz, zt_run_crc_label
			pop		bc
			djnz	zt_run_crc
			call	rd_byte
			ld		b, a
			ld		de, ZT_REC
zt_run_rec:
			call	rd_byte
			ld		[de], a
			inc		de
			djnz	zt_run_rec
			call	test_begin

			xor		a, a
			out		[PSG_ADDR], a
			ld		a, 0xBF
			out		[PSG_WRITE], a
			call	zt_call
			defb	0xED, 0x56					; im 1
			di
			ld		hl, zt_got
			ld		[hl], b
			inc		hl
			ld		[hl], c
			inc		hl
			ld		[hl], d
			inc		hl
			ld		[hl], e
			ld		hl, 1
			ld		[vec_no], hl

			ld		a, [zt_ncrc]
			ld		b, a
			ld		hl, stat_buf
zt_run_cmp:
			push	bc
			ld		de, zt_got
			ld		bc, 0x0400
zt_run_cmp_byte:
			ld		a, [de]
			xor		a, [hl]
			or		a, c
			ld		c, a
			inc		de
			inc		hl
			djnz	zt_run_cmp_byte
			ld		a, c
			pop		bc
			or		a, a
			jr		z, zt_run_match
zt_run_cmp_skip:
			ld		a, [hl]
			inc		hl
			or		a, a
			jr		nz, zt_run_cmp_skip
			djnz	zt_run_cmp
			call	print_zt_ng
			ld		hl, [err_cnt]
			inc		hl
			ld		[err_cnt], hl
			jp		test_end

zt_run_match:
			ld		a, [hl]
			or		a, a
			jp		z, test_end
			push	hl
			call	lb_clear
			ld		de, msg_indent
			call	lb_str
			call	lb_cpu
			ld		de, name_buf
			call	lb_str
			ld		de, msg_zt_as
			call	lb_str
			pop		de
			call	lb_str
			call	emit_line
			jp		test_end

zt_call:
			ld		hl, [ZT_ADDR + 2]
			push	hl
			ld		hl, ZT_REC
			ret

print_zt_ng:
			call	lb_clear
			ld		de, msg_ng
			call	lb_str
			call	lb_cpu
			ld		de, name_buf
			call	lb_str
			call	emit_line
			call	lb_clear
			ld		de, msg_indent
			call	lb_str
			ld		de, msg_got
			call	lb_str
			ld		hl, zt_got
			call	lb_hex32
			ld		de, msg_exp
			call	lb_str
			ld		hl, stat_buf
			call	lb_hex32
			jp		emit_line

;	input: hl = 4 bytes ( MSB first )
lb_hex32:
			ld		b, 4
lb_hex32_loop:
			ld		a, [hl]
			call	lb_hex8
			inc		hl
			djnz	lb_hex32_loop
			ret

; ----------------------------------------------------------------------------
;	directed tests
; ----------------------------------------------------------------------------
;	[04][name 0][id]
;	id 0 : R800 ED 63 nn nn ( FS-A1GT : writes H to 6363h, (nn) is not written )
;		6363h is a bank register of this cartridge, so the instruction is run
;		by a RAM routine with page 1 switched to RAM.
ED63_A8			:= stat_buf + 0
ED63_SSL		:= stat_buf + 1
ED63_GOT		:= stat_buf + 2		; 6362h, 6363h, 6364h
ED63_NN			:= stat_buf + 5		; 2
ED63_HL			:= stat_buf + 7		; 2
ED63_IN			:= stat_buf + 9		; 2
ED63_PTR		:= stat_buf + 11	; 2

special_test:
			call	read_name
			call	show_progress
			call	rd_byte
			or		a, a
			jp		nz, bad_stream
			call	test_begin
			; page 1 <- RAM ( same slot as page 3 )
			ld		a, [orig_a8]
			ld		b, a
			rrca
			rrca
			rrca
			rrca
			and		a, 0x0C
			ld		c, a
			ld		a, b
			and		a, 0xF3
			or		a, c
			ld		[ED63_A8], a
			ld		a, [orig_ssl]
			ld		b, a
			rrca
			rrca
			rrca
			rrca
			and		a, 0x0C
			ld		c, a
			ld		a, b
			and		a, 0xF3
			or		a, c
			ld		[ED63_SSL], a
			ld		hl, ed63_code
			ld		de, THREAD_ADDR
			ld		bc, ed63_code_end - ed63_code
			ldir
			ld		hl, ed63_hl_tbl
special_test_loop:
			ld		e, [hl]
			inc		hl
			ld		d, [hl]
			inc		hl
			ld		[ED63_PTR], hl
			ex		de, hl
			call	THREAD_ADDR
			call	ed63_check
			call	vec_next
			ld		hl, [ED63_PTR]
			ld		a, l
			cp		a, ed63_hl_tbl_end & 0xFF
			jr		nz, special_test_loop
			ld		a, h
			cp		a, ed63_hl_tbl_end >> 8
			jr		nz, special_test_loop
			jp		test_end

ed63_check:
			ld		a, [ED63_GOT + 0]
			cp		a, 0x5A
			jr		nz, ed63_check_ng
			ld		a, [ED63_GOT + 2]
			cp		a, 0x5A
			jr		nz, ed63_check_ng
			ld		a, [ED63_IN + 1]
			ld		b, a
			ld		a, [ED63_GOT + 1]
			cp		a, b
			jr		nz, ed63_check_ng
			ld		hl, [ED63_NN]
			ld		de, 0x5A5A
			or		a, a
			sbc		hl, de
			jr		nz, ed63_check_ng
			ld		hl, [ED63_HL]
			ld		de, [ED63_IN]
			or		a, a
			sbc		hl, de
			ret		z
ed63_check_ng:
			ld		hl, [vec_err]
			ld		a, h
			or		a, l
			inc		hl
			ld		[vec_err], hl
			jr		nz, ed63_check_detail
			call	lb_clear
			ld		de, msg_ng
			call	lb_str
			call	lb_cpu
			ld		de, name_buf
			call	lb_str
			call	emit_line
ed63_check_detail:
			call	lb_clear
			ld		de, msg_in
			call	lb_str
			ld		hl, [ED63_IN]
			call	lb_hex16
			ld		de, msg_got
			call	lb_str
			ld		hl, ED63_GOT
			ld		b, 3
ed63_check_got:
			ld		a, [hl]
			call	lb_hex8
			ld		a, 0x20
			call	lb_chr
			inc		hl
			djnz	ed63_check_got
			ld		hl, [ED63_NN]
			call	lb_hex16
			ld		a, 0x20
			call	lb_chr
			ld		hl, [ED63_HL]
			call	lb_hex16
			jp		emit_line

;	copied to THREAD_ADDR ( position independent )
;	input: hl = HL for ED 63
ed63_code:
			ld		[ED63_IN], hl
			ld		a, [ram_exp]
			or		a, a
			jr		z, ed63_code_a8
			ld		a, [ED63_SSL]
			ld		[0xFFFF], a
ed63_code_a8:
			ld		a, [ED63_A8]
			out		[PPI_SLOT], a
			ld		hl, [0x6362]
			push	hl
			ld		a, [0x6364]
			push	af
			ld		a, 0x5A
			ld		[0x6362], a
			ld		[0x6363], a
			ld		[0x6364], a
			ld		hl, 0x5A5A
			ld		[WIN_ADDR], hl
			ld		hl, [ED63_IN]
			defb	0xED, 0x63
			defw	WIN_ADDR
			ld		[ED63_HL], hl
			ld		hl, [0x6362]
			ld		[ED63_GOT + 0], hl
			ld		a, [0x6364]
			ld		[ED63_GOT + 2], a
			ld		hl, [WIN_ADDR]
			ld		[ED63_NN], hl
			pop		af
			ld		[0x6364], a
			pop		hl
			ld		[0x6362], hl
			ld		a, [orig_a8]
			out		[PPI_SLOT], a
			ld		a, [ram_exp]
			or		a, a
			ret		z
			ld		a, [orig_ssl]
			ld		[0xFFFF], a
			ret
ed63_code_end:

ed63_hl_tbl:
			defw	0x8100, 0x1234, 0xFFFF, 0x00A5, 0x6363, 0x5A00
ed63_hl_tbl_end:

; ----------------------------------------------------------------------------
;	screen
; ----------------------------------------------------------------------------
init_screen:
			ld		a, 15
			ld		[FORCLR], a
			ld		a, 4
			ld		[BAKCLR], a
			ld		a, 7
			ld		[BDRCLR], a
			ld		a, 1
			call	CHGMOD
			call	CHGCLR
			di
			ld		a, [RG1SAV]
			and		a, 0xDF
			out		[VDP_CTRL], a
			ld		a, 0x81
			out		[VDP_CTRL], a
			xor		a, a
			out		[VDP_CTRL], a
			ld		a, 0x8E
			out		[VDP_CTRL], a

			ld		hl, SHADOW
			ld		de, SHADOW + 1
			ld		bc, SCROLL_ROWS * 32 - 1
			ld		[hl], 0x20
			ldir
			call	flush_shadow

			call	lb_clear
			ld		hl, line_buf
			ld		b, 32
init_screen_sep:
			ld		[hl], 0x2D
			inc		hl
			djnz	init_screen_sep
			ld		a, 2
			call	write_row
			call	lb_clear
			ld		de, msg_title
			call	lb_str
			ld		a, 1
			jp		write_row

;	input: hl = VRAM address
set_vram_write:
			ld		a, l
			out		[VDP_CTRL], a
			ld		a, h
			and		a, 0x3F
			or		a, 0x40
			out		[VDP_CTRL], a
			ret

;	input: a = row
write_row:
			ld		l, a
			ld		h, 0
			add		hl, hl
			add		hl, hl
			add		hl, hl
			add		hl, hl
			add		hl, hl
			ld		de, NAME_TBL
			add		hl, de
			call	set_vram_write
			ld		hl, line_buf
			ld		b, 32
write_row_loop:
			ld		a, [hl]
			out		[VDP_DATA], a
			inc		hl
			djnz	write_row_loop
			ret

emit_line:
			ld		hl, SHADOW + 32
			ld		de, SHADOW
			ld		bc, ( SCROLL_ROWS - 1 ) * 32
			ldir
			ld		hl, line_buf
			ld		bc, 32
			ldir
flush_shadow:
			ld		hl, NAME_TBL + SCROLL_TOP * 32
			call	set_vram_write
			ld		hl, SHADOW
			ld		bc, SCROLL_ROWS * 32
flush_shadow_loop:
			ld		a, [hl]
			out		[VDP_DATA], a
			inc		hl
			dec		bc
			ld		a, b
			or		a, c
			jr		nz, flush_shadow_loop
			ret

show_progress:
			call	lb_clear
			call	lb_cpu
			ld		hl, [done_cnt]
			inc		hl
			call	lb_dec5
			ld		a, 0x20
			call	lb_chr
			ld		de, name_buf
			call	lb_str
			ld		a, 1
			jp		write_row

draw_status:
			call	lb_clear
			ld		de, msg_tot
			call	lb_str
			ld		hl, [total]
			call	lb_dec5
			ld		de, msg_done
			call	lb_str
			ld		hl, [done_cnt]
			call	lb_dec5
			ld		de, msg_err
			call	lb_str
			ld		hl, [err_cnt]
			call	lb_dec5
			xor		a, a
			jp		write_row

spin_step:
			ld		a, [spin]
			inc		a
			and		a, 3
			ld		[spin], a
			ld		e, a
			ld		d, 0
			ld		hl, spin_chars
			add		hl, de
			ld		b, [hl]
			ld		hl, NAME_TBL + 32 + 31
			call	set_vram_write
			ld		a, b
			out		[VDP_DATA], a
			ret

; ----------------------------------------------------------------------------
;	line builder
; ----------------------------------------------------------------------------
lb_clear:
			ld		hl, line_buf
			ld		[lb_ptr], hl
			ld		b, 32
lb_clear_loop:
			ld		[hl], 0x20
			inc		hl
			djnz	lb_clear_loop
			ret

;	input: a = character (all registers except af are preserved)
lb_chr:
			push	hl
			ld		hl, [lb_ptr]
			push	af
			ld		a, l
			cp		a, LINE_END & 0xFF
			jr		nc, lb_chr_full
			pop		af
			ld		[hl], a
			inc		hl
			ld		[lb_ptr], hl
			pop		hl
			ret
lb_chr_full:
			pop		af
			pop		hl
			ret

;	input: de = string (zero terminated)
lb_str:
			ld		a, [de]
			or		a, a
			ret		z
			call	lb_chr
			inc		de
			jr		lb_str

lb_cpu:
			ld		a, [cpu_mode]
			ld		de, msg_z80
			or		a, a
			jr		z, lb_str
			ld		de, msg_r800
			jr		lb_str

lb_hex16:
			ld		a, h
			call	lb_hex8
			ld		a, l
lb_hex8:
			push	af
			rrca
			rrca
			rrca
			rrca
			call	lb_nibble
			pop		af
lb_nibble:
			and		a, 0x0F
			cp		a, 10
			jr		c, lb_nibble_digit
			add		a, 7
lb_nibble_digit:
			add		a, 0x30
			jp		lb_chr

;	input: hl = value
lb_dec5:
			ld		de, 10000
			call	lb_dec_digit
			ld		de, 1000
			call	lb_dec_digit
			ld		de, 100
			call	lb_dec_digit
			ld		de, 10
			call	lb_dec_digit
			ld		de, 1
lb_dec_digit:
			ld		b, 0x30
lb_dec_digit_loop:
			or		a, a
			sbc		hl, de
			jr		c, lb_dec_digit_end
			inc		b
			jr		lb_dec_digit_loop
lb_dec_digit_end:
			add		hl, de
			ld		a, b
			jp		lb_chr

